$ErrorActionPreference='Stop';$ScriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path;. (Join-Path (Split-Path -Parent $ScriptDir) 'lib/common.ps1')
if(Test-Command python){$v=(& python --version 2>&1);if(Test-VersionGE $v '3.12.0'){Write-Ok "Python $v ya instalado";if(-not(Test-Command poetry)){& python -m pip install --user --quiet poetry};exit 0}}
if(-not(Test-Command winget)){throw 'winget no disponible. Instala App Installer desde Microsoft Store.'};& winget install --id Python.Python.3.12 --silent --accept-package-agreements --accept-source-agreements;$machine=[Environment]::GetEnvironmentVariable('PATH','Machine');$user=[Environment]::GetEnvironmentVariable('PATH','User');$env:PATH="$machine;$user";if(-not(Test-Command python)){throw 'python no disponible tras instalación'};Write-Ok "Python $(& python --version)";if(-not(Test-Command poetry)){& python -m pip install --user --quiet poetry}
